72	    /**
73	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
74	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
