271	    /**
272	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
273	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
274	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
275	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The code
276	     * carries no sequence number: it is a deterministic function of the owner's region and identity.
277	     *
278	     * @param owner the owner being created, with its region-determining postcode and city populated
279	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
280	     * @return the region-and-hash customer code for the owner being created
281	     */
282	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
283	        String region = ownerMapper.toRegion(owner);
284	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
285	        return region + "-" + hash8;
286	    }
287	
288	    /**
289	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
290	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
291	     */
292	    private static String sha256Hex8(String value) {
293	        try {
294	            byte[] digest = MessageDigest.getInstance("SHA-256")
295	                .digest(value.getBytes(StandardCharsets.UTF_8));
296	            StringBuilder sb = new StringBuilder();
297	            for (byte b : digest) {
298	                sb.append(String.format("%02X", b));
299	            }
300	            return sb.substring(0, 8);
301	        }
302	        catch (NoSuchAlgorithmException e) {
303	            throw new IllegalStateException("SHA-256 not available", e);
304	        }
305	    }
306	
307	    /**
308	     * Counts the existing owners (those already persisted before this create) whose first and last
309	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
310	     * the new owner as its {@code namesakeCount} and echoed back on reads.
311	     *
312	     * @param firstName the incoming owner's first name (already validated non-blank)
313	     * @param lastName the incoming owner's last name (already validated non-blank)
314	     * @return the number of existing namesakes sharing both names case-insensitively
315	     */
316	    private int countNamesakes(String firstName, String lastName) {
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
319	                && lastName.equalsIgnoreCase(existing.getLastName()))
320	            .count();
321	    }
