323	    /**
324	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
325	     * whitespace-only), so the caller can reject the request listing every offending field.
326	     */
327	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
328	        if (value == null || value.isBlank()) {
329	            missingFields.add(fieldName);
330	        }
331	    }
