333	    /**
334	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
335	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
336	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
337	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
338	     * {@code "+61412345678"}.
339	     *
340	     * @param telephone the raw telephone value from the request
341	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
342	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
343	     */
344	    private static String normalizeTelephone(String telephone) {
345	        String e164 = toE164(telephone);
346	        if (e164 == null) {
347	            throw new InvalidFieldValueException("telephone",
348	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
349	        }
350	        return e164;
351	    }
352	
353	    /**
354	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
355	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
356	     * owners' stored numbers when detecting duplicates.
357	     */
358	    private static String toE164(String telephone) {
359	        if (telephone == null) {
360	            return null;
361	        }
362	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
363	        String digits;
364	        if (cleaned.startsWith("+")) {
365	            digits = cleaned.substring(1);
366	        } else {
367	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
368	            digits = "61" + national;
369	        }
370	        if (!digits.matches("[0-9]{8,15}")) {
371	            return null;
372	        }
373	        if (!hasValidNationalLength(digits)) {
374	            return null;
375	        }
376	        return "+" + digits;
377	    }
378	
379	    /**
380	     * Checks the national-number length against the country code for the country codes that pin one.
381	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
382	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
383	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
384	     */
385	    private static boolean hasValidNationalLength(String digits) {
386	        if (digits.startsWith("61")) {
387	            return digits.length() - 2 == 9;
388	        }
389	        if (digits.startsWith("1")) {
390	            return digits.length() - 1 == 10;
391	        }
392	        return true;
393	    }
394	
395	    /**
396	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
397	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
398	     *
399	     * @param email the raw email value from the request (already known to be non-null)
400	     * @return the lower-cased email to be stored and returned
401	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
402	     */
403	    private static String normalizeEmail(String email) {
404	        String trimmed = email.trim();
405	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
406	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
407	        }
408	        return trimmed.toLowerCase(Locale.ROOT);
409	    }
