411	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
412	    private static final int MAX_OWNERS_PER_CITY = 50;
413	
414	    /**
415	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
416	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
417	     * been validated non-blank.
418	     *
419	     * @param city the incoming owner's city (already validated non-blank)
420	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
421	     */
422	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
423	    private static final int MAX_OWNERS_PER_DAY = 100;
424	
425	    /**
426	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
427	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
428	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
429	     * date rolled forward to a business day), so this caps the number that may be created per day.
430	     *
431	     * @param businessDay the adjusted business-day registration date of the owner being created
432	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
433	     */
434	    /**
435	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
436	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
437	     */
438	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
439	
440	    /**
441	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
442	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
443	     * owner's registration date, otherwise {@code false}.
444	     *
445	     * @param owner the owner to map
446	     * @return the owner DTO with its bulk-signup warning flag populated
447	     */
448	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
449	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
450	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
451	        return ownerDto;
452	    }
453	
454	    /**
455	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
456	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
457	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
458	     */
459	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
460	        if (registrationDate == null) {
461	            return false;
462	        }
463	        long registeredThatDay = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
465	            .count();
466	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
467	    }
468	
469	    private void requireDailyLimitNotReached(LocalDate businessDay) {
470	        long registeredThatDay = this.clinicService.findAllOwners().stream()
471	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
472	            .count();
473	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
474	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
475	        }
476	    }
477	
478	    /**
479	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
480	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
481	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
482	     * is recorded on the next business day, and every value derived from the registration date uses the
483	     * adjusted date.
484	     *
485	     * @param date the effective registration date (supplied or defaulted), never {@code null}
486	     * @return the same date, or the next Monday when {@code date} is a weekend
487	     */
488	    private static LocalDate toBusinessDay(LocalDate date) {
489	        DayOfWeek day = date.getDayOfWeek();
490	        if (day == DayOfWeek.SATURDAY) {
491	            return date.plusDays(2);
492	        }
493	        if (day == DayOfWeek.SUNDAY) {
494	            return date.plusDays(1);
495	        }
496	        return date;
497	    }
498	
499	    /** Matches a well-formed postcode: exactly four decimal digits. */
500	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
501	
502	    /**
503	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
504	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
505	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
506	     * present here and accepts any well-formed postcode.
507	     */
508	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
509	        "NSW", new int[] {2000, 2099},
510	        "VIC", new int[] {3000, 3099},
511	        "QLD", new int[] {4000, 4099});
512	
513	    /**
514	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
515	     * optional, so the request contract stays backward-compatible). When present it must be exactly
516	     * four digits and, for a city whose region is known, fall within that region's inclusive range
517	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
518	     * postcode. A malformed or out-of-range value is rejected with a 400.
519	     *
520	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
521	     * @param city the owner's city, used to look up the region whose range constrains the postcode
522	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
523	     */
524	    private void validatePostcode(String postcode, String city) {
525	        if (postcode == null) {
526	            return;
527	        }
528	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
529	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
530	        }
531	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
532	        int[] range = REGION_POSTCODES.get(region);
533	        if (range == null) {
534	            return;
535	        }
536	        int value = Integer.parseInt(postcode);
537	        if (value < range[0] || value > range[1]) {
538	            throw new InvalidFieldValueException("postcode",
539	                "Postcode must be valid for the city's region " + region);
540	        }
541	    }
542	
543	    /**
544	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
545	     * date defaults to the server date). When present it must not be later than the current server
546	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
547	     *
548	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
549	     * @throws InvalidFieldValueException if the supplied date is later than the server date
550	     */
551	    private void validateRegistrationDate(LocalDate registrationDate) {
552	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
553	            throw new InvalidFieldValueException("registrationDate",
554	                "Registration date must not be later than the current date");
555	        }
556	    }
557	
558	    private void requireCityBelowCapacity(String city) {
559	        long cityOwners = this.clinicService.findAllOwners().stream()
560	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
561	            .count();
562	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
563	            throw new CityAtCapacityException(city);
564	        }
565	    }
566	
567	    /**
568	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
569	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
570	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
571	     * former separate telephone, email and household checks. Because the telephone is part of the
572	     * key, two members of the same household (same {@code householdId}) with different telephones
573	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
574	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
575	     *
576	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
577	     *              already populated
578	     * @throws DuplicateIdentityException if another owner already has this exact identity key
579	     */
580	    private void requireUniqueIdentity(Owner owner) {
581	        String identityKey = ownerMapper.toIdentityKey(owner);
582	        boolean taken = this.clinicService.findAllOwners().stream()
583	            .map(ownerMapper::toIdentityKey)
584	            .anyMatch(identityKey::equals);
585	        if (taken) {
586	            throw new DuplicateIdentityException(identityKey);
587	        }
588	    }
589	
590	    /**
591	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate
592	     * identity check has passed, so the owner is known not to be an exact duplicate. When an existing
593	     * owner shares this owner's last name (compared case-insensitively) and postcode but carries a
594	     * different (normalized) telephone, the owner is a possible duplicate: {@code possibleDuplicate}
595	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest
596	     * such owner by id when more than one matches). Otherwise {@code possibleDuplicate} is set
597	     * {@code false} and {@code possibleDuplicateOf} left null. A blank postcode never matches, since
598	     * there is then no postcode to share.
599	     *
600	     * @param owner the incoming owner, with its last name, postcode and normalized telephone populated
601	     */
602	    private void markPossibleDuplicate(Owner owner) {
603	        owner.setPossibleDuplicate(false);
604	        owner.setPossibleDuplicateOf(null);
605	        String postcode = owner.getPostcode();
606	        if (postcode == null || postcode.isBlank()) {
607	            return;
608	        }
609	        String lastName = owner.getLastName();
610	        String telephone = owner.getTelephone();
611	        this.clinicService.findAllOwners().stream()
612	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
613	                && postcode.equals(existing.getPostcode())
614	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
615	            .min(java.util.Comparator.comparing(Owner::getId))
616	            .ifPresent(match -> {
617	                owner.setPossibleDuplicate(true);
618	                owner.setPossibleDuplicateOf(match.getId());
619	            });
620	    }
621	
622	    /**
623	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
624	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
625	     * comparisons are case-insensitive.
626	     */
627	    private static String normalizeForHousehold(String value) {
628	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
629	    }
630	
631	    /**
632	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
633	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
634	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
635	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
636	     * value normalizes to the empty string, so the required-field check rejects an address that is
637	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
638	     *
639	     * @param address the raw address value from the request (may be {@code null})
640	     * @return the normalized address, or the empty string when blank after normalization
641	     */
642	    private static String normalizeAddress(String address) {
643	        if (address == null) {
644	            return "";
645	        }
646	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
647	        if (collapsed.isEmpty()) {
648	            return "";
649	        }
650	        String[] tokens = collapsed.split(" ");
651	        StringBuilder sb = new StringBuilder();
652	        for (String token : tokens) {
653	            String expanded = switch (token) {
654	                case "ST" -> "STREET";
655	                case "RD" -> "ROAD";
656	                case "AVE" -> "AVENUE";
657	                default -> token;
658	            };
659	            if (sb.length() > 0) {
660	                sb.append(' ');
661	            }
662	            sb.append(expanded);
663	        }
664	        return sb.toString();
665	    }
666	
667	    /**
668	     * Derives the comparison key for an address used by household-duplicate detection and the shared
669	     * household identifier: the address is first put in its canonical normalized form and then
670	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
671	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
672	     */
673	    private static String householdAddressKey(String address) {
674	        return normalizeForHousehold(normalizeAddress(address));
675	    }
676	
677	    /**
678	     * Back-fills the shared {@code householdId} onto every existing member of the household
679	     * identified by this last name and address (same normalized last name and address) that does not
680	     * already carry it, so the whole household agrees on the identifier. Members that predate this
681	     * feature (or were created without opting in) are updated to the shared value. Called only after
682	     * the joining owner has passed the identity check, so a rejected request leaves existing owners
683	     * untouched.
684	     *
685	     * @param lastName the joining owner's last name (already validated non-blank)
686	     * @param address the joining owner's address (already validated non-blank)
687	     * @param householdId the shared household identifier for this last name and address
688	     */
689	    private void backfillHousehold(String lastName, String address, String householdId) {
690	        String normalizedLastName = normalizeForHousehold(lastName);
691	        String normalizedAddress = householdAddressKey(address);
692	        this.clinicService.findAllOwners().stream()
693	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
694	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
695	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
696	            .forEach(existing -> {
697	                existing.setHouseholdId(householdId);
698	                this.clinicService.saveOwner(existing);
699	            });
700	    }
701	
702	    /**
703	     * Derives a stable household identifier from the already-normalized last name and address as the
704	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
705	     * always maps to the same identifier.
706	     */
707	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
708	        try {
709	            byte[] digest = MessageDigest.getInstance("SHA-256")
710	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
711	            StringBuilder sb = new StringBuilder();
712	            for (byte b : digest) {
713	                sb.append(String.format("%02X", b));
714	            }
715	            return sb.substring(0, 12);
716	        }
717	        catch (NoSuchAlgorithmException e) {
718	            throw new IllegalStateException("SHA-256 not available", e);
719	        }
720	    }
721	}
